        margin: 0;
        font-size: clamp(1.7rem, 3vw, 2.4rem);
        line-height: 1.1;
      }

      .subtle {
        margin: 12px 0 0;
        color: var(--muted);
        max-width: 56ch;
        line-height: 1.6;
      }

      .preview {
        padding: 24px;
        display: grid;
        gap: 20px;
      }

      .image-card {
        background: linear-gradient(180deg, rgba(15, 23, 42, 0.92), rgba(2, 6, 23, 0.96));
