          linear-gradient(145deg, #111827 0%, #1f2937 55%, #0f172a 100%);
        border: 1px solid rgba(255, 255, 255, 0.06);
      }

      .image-frame::after {
        content: "";
        position: absolute;
        inset: 0;
        background:
          linear-gradient(135deg, rgba(255, 255, 255, 0.12), transparent 30%),
          linear-gradient(0deg, rgba(0, 0, 0, 0.32), transparent 42%);
        pointer-events: none;
      }

      .mock-image {
        width: 100%;
        height: 100%;
        display: block;
        object-fit: cover;
      }

      .meta-row {
        display: flex;
        justify-content: space-between;
        gap: 16px;
        align-items: center;
        flex-wrap: wrap;
        margin-top: 16px;
      }

      .meta {
        min-width: 0;
      }

      .meta strong {
        display: block;
        font-size: 1rem;
        margin-bottom: 4px;
      }

      .meta span {
        color: var(--muted);
        font-size: 0.95rem;
      }

      .trigger,
      .secondary,
      .destructive {
        appearance: none;
        border: 0;
        border-radius: 999px;
        font: inherit;
        font-weight: 650;
        cursor: pointer;
        transition: transform 160ms ease, box-shadow 160ms ease, background-color 160ms ease, opacity 160ms ease;
      }

      .trigger,
      .secondary {
        padding: 0.9rem 1.2rem;
      }

      .trigger {
        color: #fff7ed;
        background: linear-gradient(180deg, var(--danger) 0%, var(--danger-strong) 100%);
        box-shadow: 0 12px 28px rgba(220, 38, 38, 0.24);
      }

      .secondary {
        color: var(--text);
        background: rgba(148, 163, 184, 0.14);
        border: 1px solid rgba(148, 163, 184, 0.18);
      }

      .trigger:hover,
      .secondary:hover,
      .destructive:hover {
        transform: translateY(-1px);
      }

      .trigger:focus-visible,
      .secondary:focus-visible,
      .destructive:focus-visible,
      .dialog-close:focus-visible {
        outline: 3px solid rgba(249, 115, 22, 0.48);
        outline-offset: 3px;
      }

      .status {
        border-top: 1px solid var(--border);
        padding: 16px 24px 24px;
        color: var(--muted);
        min-height: 3.5rem;
        display: flex;
        align-items: center;
      }

      .status[data-tone="success"] {
        color: #86efac;
      }

      dialog {
        width: min(92vw, 460px);
        border: 1px solid rgba(255, 255, 255, 0.08);
        border-radius: 28px;
        padding: 0;
        background: linear-gradient(180deg, rgba(17, 24, 39, 0.98), rgba(15, 23, 42, 0.98));
        color: var(--text);
        box-shadow: var(--shadow);
      }

      dialog::backdrop {
        background: rgba(2, 6, 23, 0.72);
        backdrop-filter: blur(10px);
      }

      .dialog-inner {
        padding: 22px;
      }

      .dialog-top {
        display: flex;
        align-items: start;
        justify-content: space-between;
        gap: 16px;
      }

      .dialog-icon {
        width: 44px;
        height: 44px;
        border-radius: 14px;
        display: grid;
        place-items: center;
        background: rgba(239, 68, 68, 0.14);
        color: #fca5a5;
