        justify-content: end;
        gap: 12px;
        flex-wrap: wrap;
      }

      .destructive {
        padding: 0.95rem 1.25rem;
        color: white;
        background: linear-gradient(180deg, #f87171 0%, #dc2626 100%);
        box-shadow: 0 16px 28px rgba(220, 38, 38, 0.25);
      }

      .dialog-close {
        border: 0;
        background: transparent;
        color: var(--muted);
        width: 36px;
        height: 36px;
        border-radius: 999px;
        cursor: pointer;
      }

      .deleted {
