              <path d="M8 6V4h8v2" />
              <path d="M10 11v5" />
              <path d="M14 11v5" />
              <path d="M6 6l1 14h10l1-14" />
            </svg>
          </div>
          <button class="dialog-close" type="button" aria-label="Close dialog">
            <svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
              <path d="M18 6 6 18" />
              <path d="M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div class="dialog-copy">
          <h2 id="delete-title">Delete this image?</h2>
          <p id="delete-desc">This will remove the image from your library and it can’t be restored from this page.</p>
        </div>

        <div class="dialog-actions">
