          <button class="destructive" type="button" data-action="confirm">Delete image</button>
        </div>
      </div>
    </dialog>

    <script>
      const app = document.getElementById("app");
      const dialog = document.getElementById("delete-dialog");

      function Header() {
        return `
          <header class="header">
            <p class="eyebrow">Library preview</p>
            <h1 id="page-title">Mountain Light</h1>
            <p class="subtle">
              Review the image before removing it from your library. The delete action opens a confirmation dialog first.
            </p>
          </header>
        `;
      }

      function ImageCard() {
        return `
          <article class="image-card" aria-label="Image details">
            <div class="image-frame">
              <svg class="mock-image" viewBox="0 0 960 600" role="img" aria-label="Preview of a sunset over mountains">
                <defs>
                  <linearGradient id="sky" x1="0%" y1="0%" x2="0%" y2="100%">
                    <stop offset="0%" stop-color="#1d4ed8" />
                    <stop offset="55%" stop-color="#7c3aed" />
                    <stop offset="100%" stop-color="#0f172a" />
                  </linearGradient>
                  <linearGradient id="sun" x1="0%" y1="0%" x2="0%" y2="100%">
                    <stop offset="0%" stop-color="#fde68a" />
                    <stop offset="100%" stop-color="#fb923c" />
                  </linearGradient>
                </defs>
                <rect width="960" height="600" fill="url(#sky)" />
                <circle cx="690" cy="160" r="76" fill="url(#sun)" opacity="0.95" />
