                <path d="M0 470 L180 360 L340 438 L500 300 L720 435 L960 290 V600 H0 Z" fill="#0b1220" />
                <path d="M0 525 C120 505 260 495 380 512 C510 530 660 550 960 515 V600 H0 Z" fill="#020617" />
              </svg>
            </div>

