              <div class="meta">
                <strong>IMG_4812.jpg</strong>
                <span>12.8 MB · Added 4 days ago</span>
              </div>
              <button class="trigger" type="button" aria-haspopup="dialog" aria-controls="delete-dialog">
                Delete image
              </button>
            </div>
          </article>
        `;
      }

      function Status() {
        return `
          <p class="status" id="status" aria-live="polite">
