          </p>
          <p class="deleted" id="deleted-state">
            <strong>Image deleted.</strong>
            This image has been removed from your library.
          </p>
        `;
      }

      function AppView() {
        return `
          <section class="shell" aria-labelledby="page-title">
            ${Header()}
            <div class="preview">
              ${ImageCard()}
            </div>
            ${Status()}
          </section>
        `;
      }

      app.innerHTML = AppView();

      const trigger = app.querySelector(".trigger");
      const status = document.getElementById("status");
      const deletedState = document.getElementById("deleted-state");
      const cancelButton = dialog.querySelector('[data-action="cancel"]');
      const confirmButton = dialog.querySelector('[data-action="confirm"]');
      const closeButton = dialog.querySelector(".dialog-close");
      const safeReturnFocus = () => trigger && typeof trigger.focus === "function" && trigger.focus();

      function openDialog() {
        if (typeof dialog.showModal === "function" && !dialog.open) {
          dialog.showModal();
        } else {
          dialog.setAttribute("open", "");
        }
      }

      function closeDialog() {
        if (dialog.open) {
          dialog.close();
        } else {
          dialog.removeAttribute("open");
        }
      }

      function confirmDelete() {
        closeDialog();
        status.dataset.tone = "success";
        status.textContent = "Deleted from your library.";
        deletedState.style.display = "block";
        trigger.disabled = true;
        trigger.setAttribute("aria-disabled", "true");
        trigger.textContent = "Deleted";
      }

      trigger.addEventListener("click", openDialog);
      cancelButton.addEventListener("click", () => {
        closeDialog();
        safeReturnFocus();
      });
      closeButton.addEventListener("click", () => {
        closeDialog();
        safeReturnFocus();
      });
      confirmButton.addEventListener("click", confirmDelete);

      dialog.addEventListener("cancel", () => {
        safeReturnFocus();
      });

      dialog.addEventListener("close", () => {
        safeReturnFocus();
      });

      dialog.addEventListener("click", (event) => {
        const rect = dialog.getBoundingClientRect();
        const clickedBackdrop =
          event.clientX < rect.left ||
          event.clientX > rect.right ||
          event.clientY < rect.top ||
          event.clientY > rect.bottom;

        if (clickedBackdrop) {
          closeDialog();
          safeReturnFocus();
        }
      });
    </script>
  </body>
